    const timer = setTimeout(() => { timedOut = true; if (typeof terminateReservationChild==='function') terminateReservationChild(proc,'SIGKILL'); else proc.kill('SIGKILL'); }, 4 * 60 * 60 * 1000);
    if (timer.unref) timer.unref();
    proc.stderr.on('data', chunk => { stderr = (stderr + chunk.toString()).slice(-8192); });
    const lines = timelineReadline.createInterface({input:proc.stdout, crlfDelay:Infinity});
    let progressRecord={};
    const sampleFps=createFpsSampler();
    lines.on('line', line => {
      if (onLine) onLine(line);
      const split=String(line).indexOf('=');
      if(split<0)return;
      const key=String(line).slice(0,split),value=String(line).slice(split+1).trim();
      if(key==='out_time_us'||key==='fps'||key==='frame')progressRecord[key]=value;
      if(key==='progress'&&typeof onProgress==='function'){
        const timeUs=Number(progressRecord.out_time_us);
        if(Number.isFinite(timeUs))try{onProgress(timeUs,sampleFps(progressRecord.frame,progressRecord.fps));}catch(_){}
        progressRecord={};
      }
    });
    proc.on('error', err => { clearTimeout(timer); if (typeof untrackReservationChild==='function') untrackReservationChild(proc); reject(err); });
    proc.on('close', (status, signal) => {
      clearTimeout(timer);
      if (typeof untrackReservationChild==='function') untrackReservationChild(proc);
      const processReason = timedOut ? 'timed out' : status !== 0 ? `failed (${status ?? signal})` : 'exited 0 but emitted stderr';
      if (status !== 0 || stderr.trim()) reject(new Error(`${bin} ${processReason}: ${stderr.trim().slice(-400)}`));
      else resolve();
    });
  });
}

async function measureStreamTimeline(ffprobe, file, streamIndex, type) {
  let first=Infinity, last=-Infinity, count=0, invalid=0;
  await runTimelineProcess(ffprobe, ['-v','error','-select_streams',String(streamIndex),'-show_packets','-show_entries','packet=pts_time,duration_time','-of','compact=p=0:nk=0',file], line => {
    const ptsMatch=line.match(/(?:^|\|)pts_time=([^|]+)/), durMatch=line.match(/(?:^|\|)duration_time=([^|]+)/);
    if (!ptsMatch) return;
    if (ptsMatch[1] === 'N/A' || !Number.isFinite(Number(ptsMatch[1]))) { invalid++; return; }
    const pts=Number(ptsMatch[1]);
    const duration=durMatch && durMatch[1] !== 'N/A' ? Number(durMatch[1]) : 0;
    first=Math.min(first,pts);
    last=Math.max(last,pts+(Number.isFinite(duration)&&duration>0?duration:0));
    count++;
  });
  if (invalid) throw new Error(`${type} timeline has ${invalid} packets with missing timestamps`);
  if (count===0 && type==='subtitle') return {empty:true};
  if (count===0 || !Number.isFinite(first) || !Number.isFinite(last) || (type==='video' && (count<2 || !(last>first)))) throw new Error(`${type} timeline is unavailable or too short to verify`);
  return {first,last,duration:last-first,packets:count,empty:false};
}

async function verifyVideoTimeline(ffprobe, ffmpeg, source, output, sourceIndex, outputIndex, tracks, updateWorker) {
  const a=await measureStreamTimeline(ffprobe,source,sourceIndex,'video');
  const b=await measureStreamTimeline(ffprobe,output,outputIndex,'video');
  const tolerance=Math.max(0.5,a.duration*0.005);
  if (Math.abs(a.duration-b.duration)>tolerance) throw new Error(`Output video duration ${b.duration.toFixed(3)}s differs from source video ${a.duration.toFixed(3)}s (tolerance ${tolerance.toFixed(3)}s)`);
  const shift=b.first-a.first;
  for (const type of ['audio','subtitle']) {
    for (const [srcIndex,dstIndex,sourceCodec] of tracks[type]) {
      if (type === 'subtitle' && sourceCodec === 'hdmv_pgs_subtitle') { await verifyPgsSegments(ffmpeg,source,output,srcIndex,dstIndex,shift); continue; }
      const s=await measureStreamTimeline(ffprobe,source,srcIndex,type);
      const d=await measureStreamTimeline(ffprobe,output,dstIndex,type);
      if (s.empty && d.empty) continue;
      if (type === 'subtitle' && !s.empty && !d.empty && d.packets < s.packets) throw new Error(`Output subtitle packet count ${d.packets} is less than source ${s.packets} for stream ${srcIndex}`);
      if (s.empty || d.empty || Math.abs((d.first-s.first)-shift)>0.1 || Math.abs((d.last-s.last)-shift)>0.1) throw new Error(`Output ${type} timeline differs from source for stream ${srcIndex}`);
    }
  }
  const decode=['-v','error','-xerror','-progress','pipe:1','-nostats','-i',output,'-map',`0:${outputIndex}`];
  for (const [,dstIndex] of tracks.audio) decode.push('-map',`0:${dstIndex}`);
  decode.push('-f','null','-');
  reportWorkerProgress(updateWorker,{percentage:92,fps:0});
  try {
    await runTimelineProcess(ffmpeg,decode,null,(timeUs,fps)=>{
      const ratio=a.duration>0?Math.min(1,Math.max(0,timeUs/1000000/a.duration)):0;
      const data={percentage:92+7*ratio};
      if(Number.isFinite(fps)&&fps>0)data.fps=fps;
      reportWorkerProgress(updateWorker,data);
    });
  } catch (outputError) {
    const sourceCorruption=[],sourceDiagnostics=[];
    const decodeSource=async (index,type) => {
      const args=['-v','error','-xerror','-i',source,'-map',`0:${index}`,'-f','null','-'];
      try {
        await runTimelineProcess(ffmpeg,args);
        sourceDiagnostics.push(`${type} source stream ${index}: decoded cleanly`);
      } catch (sourceError) {
        const detail=String(sourceError?.message || sourceError);
        const recognized=type==='video'?isKnownVideoCorruptionDiagnostic(detail):isKnownAudioCorruptionDiagnostic(detail);
        sourceDiagnostics.push(`${type} source stream ${index}: ${recognized?'recognized corruption':'decode diagnostic'}: ${detail.slice(-300)}`);
        if(recognized)sourceCorruption.push(`${type} source stream ${index}: ${detail.slice(-500)}`);
      }
    };
    await decodeSource(sourceIndex,'video');
    for (const [srcIndex] of tracks.audio) await decodeSource(srcIndex,'audio');
    const candidateDetail=String(outputError?.message || outputError).slice(-500);
    const sourceDetail=sourceDiagnostics.join(' | ').slice(-700) || 'source decode details unavailable';
    if(sourceCorruption.length)throw new Error(`[Source media corruption] ${sourceCorruption.join(' | ')}; candidate decode failed: ${candidateDetail}; source decode details: ${sourceDetail}`);
    throw new Error(`Candidate video/audio decode failed; strict source decodes did not confirm known source corruption. Source decode details: ${sourceDetail}; candidate decode: ${candidateDetail}`);
  }
  return {sourceDuration:a.duration,outputDuration:b.duration};
}

const validateOutput = async (ffprobeBin, sourcePath, outputPath, expected) => {
  const probe = (file) => JSON.parse(execFileSync(ffprobeBin,
    ["-v", "error", "-show_format", "-show_streams", "-of", "json", file],
    { encoding: "utf8", maxBuffer: 16 * 1024 * 1024, timeout: 120000 }));
  const src = probe(sourcePath);
  const dst = probe(outputPath);

  // 1. Video stream check
  const video = (dst.streams || []).filter(s => s.codec_type === "video" && !s.disposition?.attached_pic && !s.disposition?.timed_thumbnails);
  if (video.length !== 1) throw new Error(`Output has ${video.length} video streams, expected 1`);
  if (expected.codec && video[0].codec_name !== expected.codec) {
    throw new Error(`Output video codec ${video[0].codec_name} does not match expected ${expected.codec}`);
  }

  if (expected.requireMarker && !Object.entries(dst.format?.tags || {}).some(([k,v]) => k.toLowerCase() === "encoded_by" && String(v) === (expected.outputMarker || "ArcAV1_QSV_V13"))) throw new Error("Output completion marker missing");
  let outputFrameScan;
  if (expected.sourceFrameScan || expected.hdr10) {
    reportWorkerProgress(expected.updateWorker,{percentage:82,fps:0});
    const expectedFrames=expected.sourceFrameScan?.sampleWindows ? estimateVideoFrames(video[0],Number(dst.format?.duration || 0)) : expected.sourceFrameScan?.frames || estimateVideoFrames(video[0],Number(dst.format?.duration || 0));
    outputFrameScan = await inspectVideoFrames(ffprobeBin,outputPath,video[0].index,{staticMetadata:!!expected.hdr10 || !!expected.hlg || !!expected.untagged,timestamps:!!expected.sourceFrameScan,expectedColor:video[0],expectedFrames,onProgress:(frames,total,complete,fps)=>reportWorkerProgress(expected.updateWorker,{percentage:82+8*(complete?1:total>0?Math.min(0.99,frames/total):0),fps})});
    reportWorkerProgress(expected.updateWorker,{percentage:91,fps:0});
    if (outputFrameScan.colorInfo.conflict) throw Error("Output frame color signaling conflicts with the stream");
    if (expected.sourceFrameScan) {
      try {
        compareVideoTimestamps(expected.sourceFrameScan,outputFrameScan);
      } catch (sampleError) {
        if (!Array.isArray(expected.sourceFrameScan.sampleWindows) || !expected.sourceFrameScan.sampleWindows.length) throw sampleError;
        const sampleDetail=String(sampleError?.message || sampleError);
        log(`[Timeline check] Sampled source/output comparison differed (${sampleDetail}); running a full CPU source scan and comparing complete frame timelines.`);
        expected.sourceFrameScan.fullTimelineCheckAttempted=true;
        let fullSourceScan;
        try {
          const fullSourceEstimate=estimateVideoFrames(sourceVideo,Number(src.format?.duration || 0));
          fullSourceScan=await inspectVideoFrames(ffprobeBin,sourcePath,sourceVideo.index,{staticMetadata:true,timestamps:true,expectedColor:sourceVideo,expectedFrames:fullSourceEstimate,onProgress:(frames,total,complete,fps)=>reportWorkerProgress(expected.updateWorker,{percentage:91+(complete?1:total>0?Math.min(0.99,frames/total):0),fps})});
        } catch (sourceScanError) {
          const detail=String(sourceScanError?.message || sourceScanError);
          if (isKnownVideoCorruptionDiagnostic(detail)) throw Error(`[Source media corruption] Full source scan confirmed malformed video data after sampled timeline mismatch: ${detail}`);
          throw Error(`Full source timeline scan failed after sampled mismatch (${sampleDetail}): ${detail}`);
        }
        if (fullSourceScan.interlaced) throw Error("Full source timeline scan found interlaced frames");
        if (fullSourceScan.colorInfo.conflict) throw Error("Full source timeline scan found conflicting frame color signaling");
        if (expected.sourceClass === "sdr") {
          validateSdrFrameSignaling("sdr",fullSourceScan);
          if (!isVerifiedSdr("sdr",fullSourceScan)) throw Error("Full source timeline scan did not confirm the SDR classification");
        }
        if (expected.hdr10) {
          if (fullSourceScan.dovi || fullSourceScan.hdr10plus || fullSourceScan.otherDynamic) throw Error("Full source timeline scan found dynamic HDR metadata on the static HDR10 route");
          checkHdrFrameStatic(expected.sourceHdr,fullSourceScan,!expected.optionalHdrStatic,!expected.optionalHdrStatic);
        }
        try {
          compareVideoTimestamps(fullSourceScan,outputFrameScan);
        } catch (fullError) {
          throw Error(`Sampled source/output timeline differed (${sampleDetail}); full source/output timeline also differed: ${fullError.message || fullError}`);
        }
        Object.assign(expected.sourceFrameScan,fullSourceScan);
        delete expected.sourceFrameScan.sampleWindows;
        expected.sourceFrameScan.fullTimelineCheckAttempted=true;
        log("[Timeline check] Full source/output frame counts and timestamps match; continuing validation after the sampled-window discrepancy.");
      }
    }
  }
  if (expected.hdr10) {
    if (!expected.sourceHdr) throw new Error("HDR10 source metadata missing");
    validateHdr10(expected.sourceHdr, video[0]);
    if (outputFrameScan.interlaced || outputFrameScan.dovi || outputFrameScan.hdr10plus || outputFrameScan.otherDynamic) throw new Error("HDR10 output contains unexpected dynamic metadata or interlacing");
    checkHdrFrameStatic(expected.sourceHdr,outputFrameScan,!expected.optionalHdrStatic,!expected.optionalHdrStatic);
  }
  if (expected.hlg) {
    validateHlg(expected.sourceHdr,video[0]);
    if (outputFrameScan.interlaced || outputFrameScan.dovi || outputFrameScan.hdr10plus || outputFrameScan.otherDynamic || outputFrameScan.staticInfo.mastering || outputFrameScan.staticInfo.light || outputFrameScan.staticInfo.conflict) throw Error("HLG output contains unexpected HDR metadata");
  }
  if (expected.untagged) {
    validateUntaggedOutput(expected.sdrSource,video[0],outputFrameScan);
    if (outputFrameScan.interlaced || outputFrameScan.dovi || outputFrameScan.hdr10plus || outputFrameScan.otherDynamic || outputFrameScan.staticInfo.mastering || outputFrameScan.staticInfo.light || outputFrameScan.staticInfo.conflict) throw Error("Untagged output contains unexpected HDR metadata");
  }

  // 2. Audio & Subtitle stream count & codec checks
  for (const type of ["audio", "subtitle"]) {
    const actualStreams = (dst.streams || []).filter(s => s.codec_type === type);
    if (actualStreams.length !== expected[type]) {
      throw new Error(`Output ${type} count ${actualStreams.length} does not match expected ${expected[type]}`);
    }
    const expectedCodecs = expected[type + "Codecs"];
    if (expectedCodecs && expectedCodecs.length > 0) {
      actualStreams.forEach((s, i) => {
        const expCodec = expectedCodecs[i];
        if (expCodec && (s.codec_name || "").toLowerCase() !== expCodec.toLowerCase()) {
          throw new Error(`Output ${type} codec ${s.codec_name} at index ${i} does not match expected ${expCodec}`);
        }
      });
    }
  }

  const sourceVideo = (src.streams || []).find(s => s.index === expected.sourceVideoIndex)
    || (src.streams || []).find(s => s.codec_type === "video" && !s.disposition?.attached_pic && !s.disposition?.timed_thumbnails);
  if (!sourceVideo) throw new Error("Source video stream unavailable for validation");
  if (!expected.hdr10 && !expected.hlg && !expected.untagged) validateSdrColor(expected.sdrSource || sourceVideo, video[0]);
  validateAspect(sourceVideo, video[0]);
  if (sourceVideo.width !== video[0].width || sourceVideo.height !== video[0].height) throw new Error("Output video dimensions differ from source");
  if (!expected.sourceFrameScan) {
    const countFrames = (file, index) => {
      const raw = execFileSync(ffprobeBin, ["-v","error","-select_streams",String(index),"-count_frames","-show_entries","stream=nb_read_frames","-of","json",file], {encoding:"utf8",timeout:4*60*60*1000,maxBuffer:1024*1024});
      const count = Number(JSON.parse(raw).streams?.[0]?.nb_read_frames);
      if (!Number.isSafeInteger(count) || count < 1) throw new Error("Video frame count unavailable");
      return count;
    };
    const sourceFrames=countFrames(sourcePath,sourceVideo.index), outputFrames=countFrames(outputPath,video[0].index);
    if (sourceFrames !== outputFrames) throw new Error(`Video frame count differs: ${sourceFrames} -> ${outputFrames}`);
  }
  const tracks = {};
  for (const type of ["audio", "subtitle"]) {
    const from = expected[type + "Indices"] || (src.streams || []).filter(s => s.codec_type === type).map(s => s.index);
    const to = (dst.streams || []).filter(s => s.codec_type === type).map(s => s.index);
    if (from.length !== to.length) throw new Error(`Expected ${type} mapping count does not match output`);
    tracks[type] = from.map((index, i) => [index, to[i], (src.streams || []).find(s => s.index === index)?.codec_name]);
  }
  return await verifyVideoTimeline(ffprobeBin, expected.ffmpegBin || "ffmpeg", sourcePath, outputPath, sourceVideo.index, video[0].index, tracks, expected.updateWorker);
};

const getFreeSpaceMB = (dirPath) => {
  try {
    const s = fs.statfsSync(dirPath, { bigint: true });
    if (s.bavail < 0n || s.bsize <= 0n) return null;
    return Number((s.bavail * s.bsize) / (1024n * 1024n));
  } catch (_) {
    try {
      const out = execFileSync("df", ["-Pk", dirPath], { encoding: "utf8", timeout: 10000, stdio: ["ignore", "pipe", "pipe"] });
      const lines = out.trim().split(/\r?\n/);
      const match = lines[lines.length - 1].match(/^.*?\s+\d+\s+\d+\s+(\d+)\s+\d+%\s+/);
      return match ? Math.floor(Number(match[1]) / 1024) : null;
    } catch (_) { return null; }
  }
};

const formatPipelineMode = (rawMode) => {
  if (!rawMode) return "Intel Arc GPU (Full Hardware)";
  const mode = rawMode.trim();
  if (mode.includes("Full QSV Hardware")) {
    if (mode.includes("HDR10")) return "Intel Arc GPU • HDR10";
    if (mode.includes("HLG")) return "Intel Arc GPU • HLG";
    return "Intel Arc GPU (Full Hardware)";
  }
  if (mode.includes("Hybrid")) {
    if (mode.includes("Fallback")) return "Hybrid Fallback (CPU Decode + GPU Encode)";
    if (mode.includes("CPU Decode")) return "Hybrid (CPU Decode + GPU Encode)";
    if (mode.includes("Downsample")) return "Hybrid (Color Conversion + GPU Encode)";
    return "Hybrid (CPU + GPU)";
  }
  if (mode.includes("Subtitle Normalization") || mode.includes("Seek Healing") || mode.includes("Compliant") || mode.includes("Remux")) {
    return "Fast Remux (Subtitles & Seek Repair)";
  }
  if (mode.includes("Bloat")) {
    return "Original Preserved (Bloat Protected)";
  }
  return mode;
};

const cleanFolder = (fullPath) => {
  if (!fullPath || fullPath === "Unknown file") return "Unknown folder";
  const parts = fullPath.split("/").filter(p => p && p !== "mnt" && p !== "media");
  if (parts.length <= 1) return "Root";
  parts.pop();
  const take = Math.min(parts.length, 3);
  return parts.slice(-take).join(" / ");
};

const buildOutputObj = (base, newPath, cleanName) => {
  const parsedNew = path.parse(newPath);
  const nameWithoutExt = cleanName || parsedNew.name.replace(/_(salvaged|healed|eac3|temp|singlepass)$/g, "");
  const obj = {
    ...base,
    _id: newPath,
    file: newPath,
    fileNameWithoutExtension: nameWithoutExt,
    container: parsedNew.ext.replace(".", "")
  };
  ["ffProbeData", "meta", "mediaInfo", "scannerReads"].forEach(k => delete obj[k]);
  try { obj.file_size = fs.statSync(newPath).size / (1024 * 1024); } catch (e) {}
  return obj;
};

const sendWebhookWithRetry = async (urlStr, payloadData, tag = "Discord Notifier", maxRetries = 3) => {
  if (!urlStr || urlStr.includes("***") || urlStr.includes("YOUR_WEBHOOK")) return;
  const url = new URL(urlStr);
  const lib = url.protocol === "https:" ? https : http;
  const postData = typeof payloadData === "string" ? payloadData : JSON.stringify(payloadData);

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const result = await new Promise((resolve) => {
      const req = lib.request({
        hostname: url.hostname,
        port: url.port || undefined,
        path: url.pathname + url.search,
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "User-Agent": "Tdarr-DiscordNotifier/1.0",
          "Content-Length": Buffer.byteLength(postData)
        }
      }, (res) => {
        let body = "";
        res.on("data", chunk => { body += chunk; });
        res.on("end", () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log(`[${tag}] Sent successfully on attempt ${attempt} (HTTP ${res.statusCode})`);
            resolve({ ok: true, statusCode: res.statusCode });
          } else if (res.statusCode === 429) {
            let retryAfter = 2000;
            try {
              const parsed = JSON.parse(body);
              if (parsed.retry_after) retryAfter = Math.ceil(parsed.retry_after * 1000);
            } catch (_) {}
            console.warn(`[${tag}] Rate limited (HTTP 429) on attempt ${attempt}. Waiting ${retryAfter}ms`);
            resolve({ ok: false, retry: true, delay: retryAfter, statusCode: 429 });
          } else if (res.statusCode >= 500) {
            console.warn(`[${tag}] Discord gateway error (HTTP ${res.statusCode}) on attempt ${attempt}`);
            resolve({ ok: false, retry: true, delay: attempt * 2000, statusCode: res.statusCode });
          } else {
            console.error(`[${tag} Fatal Error] HTTP ${res.statusCode}: ${body}`);
            resolve({ ok: false, retry: false, statusCode: res.statusCode });
          }
        });
      });

      req.on("error", (err) => {
        console.warn(`[${tag}] Network error on attempt ${attempt}: ${err.message || err}`);
        resolve({ ok: false, retry: true, delay: attempt * 2000, error: err });
      });

      req.setTimeout(15000, () => {
        console.warn(`[${tag}] Socket timeout (15s) on attempt ${attempt}`);
        req.destroy();
        resolve({ ok: false, retry: true, delay: attempt * 2000, timeout: true });
      });

      req.write(postData);
      req.end();
    });

    if (result.ok || !result.retry || attempt === maxRetries) {
      if (!result.ok && attempt === maxRetries) {
        console.error(`[${tag}] Failed to deliver notification after ${maxRetries} attempts.`);
      }
      break;
    }

    const waitMs = result.delay || (attempt * 2000);
    await new Promise(r => setTimeout(r, waitMs));
  }
};

