        return false;
      }
      return true;
    });
    if (nonZho.length > 0) candidateAudio = nonZho;
  }

  // Redundant Legacy Core & Downmix Pruning per canonical language
  const prunedAudioIndices = new Set();
  const langAudioMap = {};
  candidateAudio.forEach(s => {
    const lang = normalizeLang(s.tags?.language || s.tags?.LANGUAGE || "und");
    if (!langAudioMap[lang]) langAudioMap[lang] = [];
    langAudioMap[lang].push(s);
  });

  Object.keys(langAudioMap).forEach(lang => {
    const tracks = langAudioMap[lang];
    const masterTrack = tracks.find(s => {
      const c = (s.codec_name || "").toLowerCase();
      const prof = (s.profile || "").toLowerCase();
      const ch = parseInt(s.channels || 0, 10);
      return (ch >= 6) && (ch > 6 || prof.includes("dts-hd") || c.startsWith("pcm_") || ["truehd", "dts-hd ma", "flac", "alac"].some(m => c.includes(m)));
    });
    const hasSurround = tracks.some(s => parseInt(s.channels || 0, 10) > 2);

    tracks.forEach(s => {
      const c = (s.codec_name || "").toLowerCase();
      const prof = (s.profile || "").toLowerCase();
      const ch = parseInt(s.channels || 0, 10);
      const title = (s.tags?.title || s.tags?.TITLE || "").toLowerCase();
      const isCommentary = s.disposition?.comment === 1 || title.includes("commentary") || title.includes("description");
      const isLossyCore = (c === "ac3") || (c === "dts" && !prof.includes("dts-hd"));

      // Omit redundant legacy core (e.g. AC3/DTS 5.1 alongside TrueHD/DTS-HD MA/FLAC/PCM master)
      if (masterTrack && s.index !== masterTrack.index && ch === 6 && isLossyCore && !isCommentary) {
        prunedAudioIndices.add(s.index);
        console.log(`[Audio Pruner] Omitted duplicate legacy core stream 0:${s.index} (${c} ${ch}ch) in favor of master stream 0:${masterTrack.index}`);
      }
      // Omit redundant AAC stereo downmix if surround exists
      if (hasSurround && tracks.length > 1 && ch <= 2 && c === "aac" && !isCommentary) {
        prunedAudioIndices.add(s.index);
        console.log(`[Audio Pruner] Omitted redundant AAC stereo downmix stream 0:${s.index} for language '${lang}'`);
      }
    });
  });

  const finalAudioStreams = candidateAudio.filter(s => !prunedAudioIndices.has(s.index));

  // 6. Subtitle Filtering & Safe Format Normalization (eng, ita, spa, und)
  const allowedSubLangs = ["eng", "ita", "spa", "und"];
  const toSrtCodecs = ["ass", "ssa", "eia_608", "c608", "cea-608", "cea-708", "mov_text", "tx3g", "webvtt", "vtt"];
  const toSrtCodecIDs = ["mov_text", "tx3g", "c608", "eia_608"];
  const inputContainer = String(args.inputFileObj?.container || path.extname(inputPath).slice(1)).toLowerCase();
  const isMatroskaContainer = ["mkv", "mka", "mks", "matroska"].includes(inputContainer);
  const shouldConvertSubToSrt = stream => {
    const codec = String(stream.codec_name || "").toLowerCase();
    const codecId = String(stream.codec_tag_string || stream.codec_id || "").toLowerCase();
    if (isMatroskaContainer && ["ass", "ssa"].includes(codec)) return false;
    return toSrtCodecs.includes(codec) || toSrtCodecIDs.includes(codecId);
  };

  const finalSubStreams = streams.filter(s => {
    if (s.codec_type !== "subtitle") return false;
    const c = (s.codec_name || "").toLowerCase();
    const cid = (s.codec_tag_string || s.codec_id || "").toLowerCase();
    // Drop corrupt 'none' or unmuxable s_text/webvtt tracks
    if (!c || c === "none" || cid === "s_text/webvtt") {
      console.log(`[Subtitle Filter] Dropping un-muxable subtitle stream 0:${s.index} (codec: ${c || cid || "none"})`);
      return false;
    }
    const lang = normalizeLang(s.tags?.language || s.tags?.LANGUAGE || "und");
    return allowedSubLangs.includes(lang);
  });

  const cleanBase = (args.originalLibraryFile?.fileNameWithoutExtension || parsed.name)
    .replace(/(_(salvaged|healed|eac3|temp|singlepass)|-TdarrCacheFile-[A-Za-z0-9_-]+)$/g, "");

  try {
  // Cache reservations permit concurrent jobs while coordinating available space.
  const reservationRootDir = process.env.TDARR_RESERVATION_ROOT || "/transcode_cache";
  const envMinFreeMB = parseInt(process.env.TDARR_MIN_FREE_SPACE_MB || args.variables?.user?.min_cache_free_mb || 0, 10);
  const minFloorMB = Number.isSafeInteger(envMinFreeMB) && envMinFreeMB > 0 ? envMinFreeMB : 20480;
  const envMinRamFreeMB = parseInt(process.env.TDARR_MIN_RAM_FREE_MB || args.variables?.user?.min_ram_free_mb || 0, 10);
  const minRamFloorMB = Number.isSafeInteger(envMinRamFreeMB) && envMinRamFreeMB > 0 ? envMinRamFreeMB : 2048;
  const envMinSystemRamFreeMB = parseInt(process.env.TDARR_MIN_SYSTEM_RAM_FREE_MB || args.variables?.user?.min_system_ram_free_mb || 0, 10);
  const minSystemRamFloorMB = Number.isSafeInteger(envMinSystemRamFreeMB) && envMinSystemRamFreeMB > 0 ? envMinSystemRamFreeMB : 4096;
  const reservedOutputBytes = ((originalSnapshot.size * 5n + 3n) / 4n) + 64n * 1024n * 1024n;
  const maxOutputBytes = reservedOutputBytes - 32n * 1024n * 1024n;
  const candidates = [];
  // Prefer bounded /dev/shm when capacity allows; configured disk paths remain fallbacks.
  for (const candidate of ["/dev/shm", process.env.TDARR_DEDICATED_CACHE, args.variables?.user?.dedicated_cache_dir, args.workDir, "/transcode_cache", "/temp", "/mnt/cache", "/app/unmappedNodeCache"]) {
    if (typeof candidate !== "string" || !path.isAbsolute(candidate) || !fs.existsSync(candidate)) continue;
    try {
      const real = fs.realpathSync(candidate);
      const fsType = fs.statfsSync(real,{bigint:true}).type;
      if (typeof fsType !== "bigint") { log(`[Cache reservation] Cannot determine filesystem type for ${candidate}; skipping.`); continue; }
      const magic = BigInt.asUintN(32,fsType);
      if (magic === 2240043254n) { log(`[Cache reservation] Skipping unbounded ramfs candidate ${candidate}.`); continue; }
      if (!candidates.includes(real)) candidates.push(real);
    } catch (err) { log(`[Cache reservation] Cannot inspect ${candidate}; trying the next cache.`); }
  }
  let selectedDir = null;
  for (const candidate of candidates) {
    try {
      const real = fs.realpathSync(candidate);
      const magic = BigInt.asUintN(32,fs.statfsSync(real,{bigint:true}).type);
      const isRamCache = magic === 16914836n;
      const floorBytes = BigInt(isRamCache ? minRamFloorMB : minFloorMB) * 1024n * 1024n;
      const systemRamFloorBytes = BigInt(isRamCache ? minSystemRamFloorMB : 0) * 1024n * 1024n;
      const handle = await reserveCapacity({root:reservationRootDir,candidate:real,bytes:reservedOutputBytes,floorBytes,systemRamFloorBytes});
      args.variables.user.cache_reservation = handle;
      selectedDir = real;
      log(`[Cache reservation] Reserved ${reservedOutputBytes} bytes on ${real} (${isRamCache ? "RAM" : "disk"}); other jobs may run when capacity permits.`);
      break;
    } catch (err) {
      if (/Insufficient available capacity for reservation/.test(String(err.message || err))) {
        log(`[Cache reservation] Insufficient available capacity on ${candidate}; trying the next candidate.`);
        continue;
      }
      throw err;
    }
  }
  if (!selectedDir) throw Error("No cache directory has enough unreserved space for this job");

  // A per-job directory prevents collisions for identical basenames.
  const targetDir = makeJobDir(selectedDir);
  const outputPath = path.join(targetDir, `${cleanBase}.mkv`);
  args.variables.user.safety_temp_dir = targetDir;
  await registerReservationWorkspace(args.variables.user.cache_reservation, targetDir);
  args.variables.user.safety_temp_output = outputPath;

  // 7. Chapter Boundary Guard (Seek Healing for out-of-bounds chapter end_time against video/container duration)
  let clampedMetaPath = null;
  let hasClampedChapters = false;
  try {
    const probeChaptersRaw = execFileSync("ffprobe", [
      "-v", "error", "-show_chapters", "-print_format", "json", inputPath
    ], { encoding: "utf8" });
    const chapData = JSON.parse(probeChaptersRaw);
    const chaps = chapData?.chapters || [];
    if (chaps.length > 0 && durationSec > 0) {
      const lastChap = chaps[chaps.length - 1];
      const lastEndSec = parseFloat(lastChap.end_time || 0);
      if (lastEndSec > durationSec + 0.1) {
        log(`[Chapter Boundary Guard] Last chapter end_time (${lastEndSec}s) exceeds video/container duration (${durationSec}s). Clamping chapter boundaries.`);
        const maxMs = Math.round(durationSec * 1000);
        const metaLines = [";FFMETADATA1"];
        chaps.forEach((c, idx) => {
          const startMs = Math.min(Math.round(parseFloat(c.start_time || 0) * 1000), maxMs);
          let endMs = Math.round(parseFloat(c.end_time || 0) * 1000);
          if (endMs > maxMs) {
            endMs = maxMs;
          }
          metaLines.push("[CHAPTER]", "TIMEBASE=1/1000", `START=${startMs}`, `END=${endMs}`);
          const title = c.tags?.title || `Chapter ${idx + 1}`;
          metaLines.push(`title=${title}`);
        });
        clampedMetaPath = path.join(targetDir, `${cleanBase}_chapters.txt`);
        fs.writeFileSync(clampedMetaPath, metaLines.join("\n"));
        hasClampedChapters = true;
      }
    }
  } catch (chapErr) {
    // Non-fatal if chapter probe fails
  }

  // Helper to append audio & subtitle mappings to any FFmpeg command array
  const langDisplayMap = {
    eng: "English",
    jpn: "Japanese",
    zho: "Chinese",
    ita: "Italian",
    spa: "Spanish",
    und: "Audio"
  };
  const codecDisplayMap = {
    opus: "Opus",
    eac3: "E-AC-3",
    ac3: "AC3",
    dts: "DTS",
    aac: "AAC",
    flac: "FLAC",
    truehd: "TrueHD",
    alac: "ALAC",
    mp3: "MP3",
    vorbis: "Vorbis"
  };

  const appendAudioAndSubArgs = (cmdArgs) => {
    if (finalAudioStreams.length > 0) {
      finalAudioStreams.forEach((s, idx) => {
        cmdArgs.push("-map", `0:${s.index}`);
        const ch = parseInt(s.channels || 0, 10);
        const c = (s.codec_name || "").toLowerCase();
        const prof = (s.profile || "").toLowerCase();
        const isTranscodedToEac3 = ch > 2 && (c !== "eac3" || ch > 6);
        let actualCodec = "Audio";
        let finalCh = ch || 2;

        // Convert surround (>2ch) to E-AC3 5.1 @ 640k unless it is already E-AC3 <=6ch
        if (isTranscodedToEac3) {
          cmdArgs.push(`-c:a:${idx}`, "eac3", `-b:a:${idx}`, "640k");
          if (ch > 6) cmdArgs.push(`-ac:a:${idx}`, "6");
          actualCodec = "E-AC-3";
          finalCh = 6;
        } else {
          cmdArgs.push(`-c:a:${idx}`, "copy");
          if (c === "dts" && prof.includes("dts-hd")) {
            actualCodec = "DTS-HD MA";
          } else {
            actualCodec = codecDisplayMap[c] || (c ? c.toUpperCase() : "Audio");
          }
        }

        // Dynamic Audio Title Normalization & Codec Tag Sanitization
        const chLayout = finalCh === 6 ? "5.1" : (finalCh === 8 ? "7.1" : (finalCh === 1 ? "Mono" : "2.0"));
        const canonLang = normalizeLang(s.tags?.language || s.tags?.LANGUAGE || "und");
        const langName = langDisplayMap[canonLang] || (canonLang ? canonLang.toUpperCase() : "Audio");
        const rawTitle = String(s.tags?.title || s.tags?.TITLE || "");
        const strippedTitle = rawTitle
          .replace(/\[[^\]]*\]|\([^)]*\)/g, " ")
          .replace(/\b(x264|x265|h264|h265|hevc|av1|10b|10bit|8bit|\d+\s*kbps)\b/gi, " ")
          .replace(/\s+/g, " ")
          .trim();
        const isGenericOrEmpty = !strippedTitle || /^(english|eng|japanese|jap|jpn|chinese|zho|chi|mandarin|cantonese|italian|ita|spanish|spa|undetermined|und|stereo|surround|mono|audio|default|main|original|track\s*\d+|\d+\.\d+|aac|ac-?3|e-?ac-?3|ddp?|opus|dts(?:-hd)?(?:\s*ma)?|truehd|flac|pcm|\s|-|\/|:)+$/i.test(strippedTitle);
        const correctedTitle = isGenericOrEmpty
          ? `${langName} [${actualCodec} ${chLayout}]`
          : `${strippedTitle} [${actualCodec} ${chLayout}]`;
        cmdArgs.push(`-metadata:s:a:${idx}`, `title=${correctedTitle}`);
      });

      // Enforce Surround = default and Stereo = non-default (0) when both exist
      const hasSurround = finalAudioStreams.some(s => parseInt(s.channels || 0, 10) > 2);
      const hasStereo = finalAudioStreams.some(s => {
        const ch = parseInt(s.channels || 0, 10);
        return ch > 0 && ch <= 2;
      });
      if (hasSurround && hasStereo) {
        let defaultSet = false;
        finalAudioStreams.forEach((s, idx) => {
          if (parseInt(s.channels || 0, 10) > 2 && !defaultSet) {
            cmdArgs.push(`-disposition:a:${idx}`, "default");
            defaultSet = true;
          } else {
            cmdArgs.push(`-disposition:a:${idx}`, "0");
          }
        });
      }
    } else {
      cmdArgs.push("-an");
    }

    if (finalSubStreams.length > 0) {
      finalSubStreams.forEach((s, idx) => {
        const c = (s.codec_name || "").toLowerCase();
        const cid = (s.codec_tag_string || s.codec_id || "").toLowerCase();
        cmdArgs.push("-map", `0:${s.index}`);
        if (shouldConvertSubToSrt(s)) {
          cmdArgs.push(`-c:s:${idx}`, "srt");
        } else {
          cmdArgs.push(`-c:s:${idx}`, "copy");
          if (c === "hdmv_pgs_subtitle") {
            cmdArgs.push(`-bsf:s:${idx}`, "setts=pts=if(eq(PTS\\,NOPTS)\\,NOPTS\\,max(PTS\\,PREV_OUTPTS+1)):dts=if(eq(DTS\\,NOPTS)\\,NOPTS\\,max(DTS\\,PREV_OUTDTS+1))");
          }
        }
      });
    } else {
      cmdArgs.push("-sn");
    }
  };

  // 8. Assemble Single-Pass FFmpeg Execution Command
  const extractFfmpegError = (stderrStr) => {
    const lines = String(stderrStr || "")
      .split("\n")
      .map(l => l.trim())
      .filter(l => l && !l.startsWith("configuration:") && !l.startsWith("lib") && !l.startsWith("ffmpeg version"));
    const specific = lines.filter(l => /\b(?:error|failed|unsupported|invalid|cannot|could not|only one of them|ratecontrol)\b/i.test(l)
      && !/discarding stream metadata .* because the stream is being re-encoded/i.test(l));
    const causal = specific.filter(l => !/task finished with error|terminating thread with error|conversion failed/i.test(l));
    const chosen = causal.length ? causal.slice(-6) : lines.slice(-12);
    return chosen.join(" | ").substring(0, 1200);
  };

  const runFfmpeg = (useHybrid = false, forceStreamCopy = false, useIcqOnly = false) => {
    const cmdArgs = ["-y", "-xerror", "-progress", "pipe:1", "-nostats", "-fflags", "+genpts+igndts"];
    const doCopyVideo = isAlreadyAV1 || forceStreamCopy;

    if (!doCopyVideo) {
      // Both Full Hardware and Hybrid modes require VAAPI->QSV device context for av1_qsv encoder
      cmdArgs.push(
        "-init_hw_device", `vaapi=va:${gpuDevice}`,
        "-init_hw_device", "qsv=hw@va",
        "-filter_hw_device", "hw"
      );
      if (!useHybrid) {
        // Full Hardware QSV Decode
        cmdArgs.push(
          "-hwaccel", "qsv",
          "-hwaccel_device", "hw",
          "-hwaccel_output_format", "qsv",
          "-extra_hw_frames", "64"
        );
      }
    }

    if (hdrLightOverride) cmdArgs.push("-content_light", hdrLightOverride);
    cmdArgs.push("-i", inputPath);
    if (is12Bit && !forceStreamCopy) cmdArgs.push("-sws_dither", "ed");

    if (hasClampedChapters && clampedMetaPath) {
      cmdArgs.push("-i", clampedMetaPath, "-map_metadata", "0", "-map_chapters", "1");
    }

    // Video Mapping & Encoding / Stream-Copy Arguments
    cmdArgs.push("-map", `0:${mainVideo.index}`);
    // Prevent FFmpeg's automatic sync mode from silently dropping or duplicating decoded frames.
    if (!doCopyVideo) cmdArgs.push("-fps_mode:v", "passthrough");
    if (hdrClass === "untagged") cmdArgs.push(...untaggedColorRangeArgs(hdrClass,sdrSource));
    if (doCopyVideo) {
      cmdArgs.push("-c:v", "copy");
    } else {
      if (useHybrid) {
        cmdArgs.push("-vf", hdrClass === "hdr10plus_hdr10" ? "sidedata=mode=delete:type=DYNAMIC_HDR_PLUS,format=p010le" : "format=p010le");
      } else if (is10Bit) {
        cmdArgs.push("-vf", "vpp_qsv");
      } else {
        cmdArgs.push("-vf", "vpp_qsv=format=p010");
      }

      if (isHdr) {
        if (isHlg) {
          cmdArgs.push("-color_primaries", "bt2020", "-color_trc", "arib-std-b67", "-colorspace", "bt2020nc");
        } else {
          cmdArgs.push("-color_primaries", "bt2020", "-color_trc", "smpte2084", "-colorspace", "bt2020nc");
        }
      }

      cmdArgs.push(
        "-c:v", "av1_qsv",
        "-preset", "slow",
        "-global_quality", `${quality}`,
        "-extbrc", "1",
        "-adaptive_i", "1",
        "-adaptive_b", "1",
        "-b_strategy", "1",
        "-g", "120"
      );
    }

    // Stamp flow signature on all encoded and bloat-fallback files to prevent re-encode loops
    if (!doCopyVideo || forceStreamCopy) {
      cmdArgs.push("-metadata:g", forceStreamCopy ? "encoded_by=ArcAV1_SeekHeal_V13" : "encoded_by=ArcAV1_QSV_V13");
    }

    // Audio & Subtitle Mappings
    appendAudioAndSubArgs(cmdArgs);

    // Purge Junk Data/Attachments & Apply Seek-Healing Muxer Stability Flags
    cmdArgs.push(
      "-map", "-0:d?",
      "-map", "-0:t?",
      "-max_interleave_delta", "0",
      "-avoid_negative_ts", "make_zero",
      "-max_muxing_queue_size", "2048",
      ...(!forceStreamCopy ? ["-fs", String(maxOutputBytes)] : []),
      outputPath
    );

    log(`[Arc AV1 Single-Pass] Executing: ${ffmpegBin} ${cmdArgs.join(" ")}`);
    const progressStart=forceStreamCopy?80:8,progressEnd=forceStreamCopy?82:80;
    // Encodes stop at source size. Remux file-size limits grow only after the shared cache ledger grants capacity.
    const processSizeLimit=forceStreamCopy?reservedOutputBytes:sourceBytes;
    const processReason=forceStreamCopy
      ? "Size guard fallback: stream-copy the source video with seek-healing mux flags; preserve audio/subtitle processing."
      : `Arc QSV AV1 encode at ICQ ${quality}; validate the resulting video, color metadata, audio, and subtitles.`;
    const workerDetails={
      CLIType:ffmpegBin,
      preset:cmdArgs.join(" "),
      workerLog:processReason,
      outputPath,
      lastPluginDetails:{
        source:"Community",
        id:"arc_av1_monolithic",
        number:"1/1"
      }
    };
    const remuxCapacity=forceStreamCopy?{
      outputPath,
      initialBytes:reservedOutputBytes,
      headroomBytes:512n*1024n*1024n,
      chunkBytes:1024n*1024n*1024n,
      grow:(requiredBytes,usedBytes)=>growCapacityReservation(args.variables.user.cache_reservation,requiredBytes,usedBytes,{marginBytes:64n*1024n*1024n}),
      onLimit:bytes=>{
        args.variables.user.cache_reservation_bytes=String(bytes);
        log(`[Cache reservation] Expanded seek-healing remux capacity to ${bytes} bytes on ${targetDir}.`);
      }
    }:undefined;
    return runLimitedFfmpeg({command:"prlimit",argv:[`--fsize=${processSizeLimit}:unlimited`, "--", ffmpegBin, ...cmdArgs],durationSec,updateWorker:args.updateWorker,workerDetails,progressStart,progressEnd,capacity:remuxCapacity});
  };

  log(`[Arc AV1] Processing ${inputPath} using global ICQ ${quality}; ${pipelineMode}`);
  const sourceBytes = Number(originalSnapshot.size);
  if (!Number.isSafeInteger(sourceBytes) || sourceBytes < 1) throw new Error("Original size is invalid");
  args.variables.user.original_size_mb = sourceBytes / (1024 * 1024);
  let isBloat = false;
  const attempt = await runSingleQuality(quality, sourceBytes, async (q) => {
    if (fs.existsSync(outputPath)) fs.unlinkSync(outputPath);
    let result = await runFfmpeg(needsProactiveHybrid, false);
    if (result.error) return {ok:false, ffmpeg:result};
    const reachedLimit = r => fs.existsSync(outputPath) && fs.statSync(outputPath).size >= sourceBytes && (r.signal === 'SIGXFSZ' || /file too large/i.test(String(r.stderr || '')));
    if (reachedLimit(result)) { log(`[Size guard] ICQ ${q} encode hit the source-size cap.`); return {ok:true,size:sourceBytes,ffmpeg:result}; }
    const decodeFailure = /error while decoding|failed to decode|decoder[^\n]*(?:error|failed)|error submitting packet to decoder|failed to get (?:a )?frame/i.test(String(result.stderr || ""));
    if (result.status !== 0 && !needsProactiveHybrid && decodeFailure) {
      log(`[Arc AV1] Full GPU decode failed at ICQ ${q}: ${extractFfmpegError(result.stderr)}. Trying CPU decode with Arc encode.`);
      if (fs.existsSync(outputPath)) fs.unlinkSync(outputPath);
      result = await runFfmpeg(true, false);
      pipelineMode = `Hybrid (CPU Decode + Arc QSV AV1 Encode)`;
      if (reachedLimit(result)) { log(`[Size guard] ICQ ${q} encode hit the source-size cap.`); return {ok:true,size:sourceBytes,ffmpeg:result}; }
    }
    if (result.status !== 0 || !fs.existsSync(outputPath)) return {ok:false, ffmpeg:result};
    if (Array.isArray(frameScan?.sampleWindows) && isKnownVideoCorruptionDiagnostic(result.stderr)) {
      sourceScanFailureDetail=await scanFullSourceAfterFailure("a recognized video decode warning during encode",80);
      if (sourceScanFailureDetail) return {ok:false,ffmpeg:{...result,status:1,stderr:`Full source scan confirmed malformed video data: ${sourceScanFailureDetail}`}};
    }
    const size = fs.statSync(outputPath).size;
    log(`[Arc AV1] ICQ ${q} produced ${size} bytes; source ${sourceBytes} bytes.`);
    return {ok:true, size, ffmpeg:result};
  });
  let res = attempt.result?.ffmpeg || {status: 1, stderr: `No smaller output at ICQ ${attempt.quality}`};
  if (!attempt.ok && attempt.reason !== "encoder") {
    if (attempt.reason !== "quality_floor") log(`[Arc AV1] Could not verify a valid output size at ICQ ${attempt.quality}.`);
    if (fs.existsSync(outputPath)) fs.unlinkSync(outputPath);
    res = {status:1, qualityFloor:attempt.reason === "quality_floor", stderr:`No smaller output at ICQ ${attempt.quality}: ${attempt.reason}`};
  }

  // Cleanup temporary clamped chapters file if created
  const cleanupChapters = () => {
    if (clampedMetaPath && fs.existsSync(clampedMetaPath)) {
      try { fs.unlinkSync(clampedMetaPath); } catch (_) {}
    }
  };

  if (res.qualityFloor) {
    log(`[Size guard] No smaller output at ICQ ${attempt.quality}; trying a source-video stream-copy remux with seek healing.`);
    try { if (fs.existsSync(outputPath)) fs.unlinkSync(outputPath); } catch (_) {}
    const remuxRes = await runFfmpeg(false, true);
    cleanupChapters();
    if (remuxRes.status !== 0 || !fs.existsSync(outputPath)) {
      try { if (fs.existsSync(outputPath)) fs.unlinkSync(outputPath); } catch (_) {}
      const remuxError = extractFfmpegError(remuxRes.stderr);
      const remuxExit = remuxRes.capacityError ? `Cache reservation growth stopped the remux: ${remuxRes.capacityError.message || remuxRes.capacityError}` : remuxRes.error ? `FFmpeg could not start: ${remuxRes.error.message || remuxRes.error}` : `FFmpeg exit ${remuxRes.status ?? "unknown"}${remuxRes.signal ? ` (${remuxRes.signal})` : ""}`;
      const remuxOutput = fs.existsSync(outputPath) ? `output ${fs.statSync(outputPath).size} bytes` : "output missing";
      const reason = `${remuxExit}; ${remuxOutput}${remuxError ? `; stderr: ${remuxError}` : ""}`;
      log(`[Size guard] Seek-healing remux failed (${reason}); original retained.`);
      return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
    }
    const remuxBytes = fs.statSync(outputPath).size;
    const remuxLimit=remuxRes.fileSizeLimit ?? reservedOutputBytes;
    if (BigInt(remuxBytes) > remuxLimit) {
      try { fs.unlinkSync(outputPath); } catch (_) {}
      log(`[Cache reservation] Seek-healing remux exceeded its granted output capacity (${remuxBytes} bytes vs ${remuxLimit}); original retained.`);
      return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
    }
    isBloat = true;
    quality = null;
    pipelineMode = "Size Bloat Fallback (Original Video Stream-Copy + Seek Healed)";
    res = {status:0,stderr:remuxRes.stderr || ""};
    log(`[Size guard] Seek-healing remux completed at ${remuxBytes} bytes (source ${sourceBytes}); ${remuxBytes>sourceBytes?"the repaired output is larger than source and will be preserved":"the repaired output is smaller than source"}. Validating before replacement.`);
  }
  if (res.status !== 0 || !fs.existsSync(outputPath)) {
    cleanupChapters();
    const errTail = extractFfmpegError(res.stderr);
    const errReason = res.error
      ? `Unable to start the size-limited encoder: ${res.error.message || res.error}`
      : errTail
      ? `FFmpeg exit ${res.status}: ${errTail}`
      : `FFmpeg process exited with status ${res.status}`;
    log(`[Arc AV1 Single-Pass] Transcode execution failed critically: ${errReason}`);
    if (Array.isArray(frameScan?.sampleWindows)) {
      if (!sourceScanFailureDetail) sourceScanFailureDetail=await scanFullSourceAfterFailure("encode failure",80);
      if (sourceScanFailureDetail) log(`[Video guard] ${sourceScanFailureDetail}; original retained.`);
    }
    const totalDurationStr = formatDuration(Date.now() - startEpoch);
    const failPayload = {
      embeds: [{
        title: `❌ ${titleName}`,
        description: [
          `⚠️ **Error:** \`${errReason.replace(/`/g, "'")}\``,
          `⏱️ **Duration:** ${totalDurationStr}`
        ].join("\n"),
        color: 15158332,
        footer: { text: "Tdarr AV1 Flow • Transcode Failure Alert" },
        timestamp: new Date().toISOString()
      }]
    };
    return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
  }

  // 9. 7-Tier Dual-Condition Dynamic Size & Quality Guard
  const outputStat = fs.statSync(outputPath);
  const newSizeMB = outputStat.size / (1024 * 1024);
  const origGB = rawSizeMB > 0 ? (rawSizeMB / 1024) : 0;
  const ratioPct = rawSizeMB > 0 ? ((newSizeMB / rawSizeMB) * 100) : 100;

  const is4K = width >= 3840 || height >= 1600;
  const is1080p = (width >= 1920 || height >= 1000) && !is4K;

  let tierName = "Tier 7: 720p / SD / Low-Res";
  let minRatioPct = 6.0;
  let maxRatioPct = 115.0;
  let minAbsoluteMB = 25;

  if (is4K) {
    if (origGB >= 40) {
      tierName = "Tier 1: Massive 4K UHD Remux (>= 40 GB)";
      minRatioPct = 1.5; maxRatioPct = 85.0; minAbsoluteMB = 300;
    } else if (origGB >= 15) {
      tierName = "Tier 2: Standard 4K Web/Rip (15 - 40 GB)";
      minRatioPct = 3.0; maxRatioPct = 95.0; minAbsoluteMB = 250;
    } else {
      tierName = "Tier 3: Light 4K Web-DL (< 15 GB)";
      minRatioPct = 4.0; maxRatioPct = 105.0; minAbsoluteMB = 200;
    }
  } else if (is1080p) {
    if (origGB >= 20) {
      tierName = "Tier 4: Heavy 1080p Remux (>= 20 GB)";
      minRatioPct = 2.5; maxRatioPct = 90.0; minAbsoluteMB = 150;
    } else if (origGB >= 5) {
      tierName = "Tier 5: Standard 1080p Blu-ray/Web (5 - 20 GB)";
      minRatioPct = 4.0; maxRatioPct = 105.0; minAbsoluteMB = 100;
    } else {
      tierName = "Tier 6: Compressed 1080p (< 5 GB)";
      minRatioPct = 5.0; maxRatioPct = 110.0; minAbsoluteMB = 50;
    }
  }

  // Require at least 15% size reduction when re-encoding an already-AV1 file
  if (isOversizedAV1) {
    maxRatioPct = Math.min(maxRatioPct, 85.0);
    tierName += " • Oversized AV1 Re-Encode (<=85% Target)";
  }

  // Dual-Condition Corrupt Protection (or < 1% on remux)
  const isUndersized = isAlreadyAV1
    ? (ratioPct < 1.0 || newSizeMB < 0.1)
    : ((ratioPct < minRatioPct) && (newSizeMB < minAbsoluteMB));
  // isBloat is set only by the strictly smaller, validated seek-heal fallback.

  if (isUndersized) {
    cleanupChapters();
