    return new Promise((resolve) => {
      let url;
      try {
        url = new URL(urlStr);
      } catch (e) {
        return resolve({ ok: false, statusCode: 0, error: e });
      }
      const lib = url.protocol === "https:" ? https : http;
      const postData = bodyObj ? JSON.stringify(bodyObj) : null;
      const headers = {
