      log(`[ARR Notifier] Could not resolve ${isSonarr ? "seriesId" : "movieId"} for '${contentFolder || filePath}' on ${target.label}`);
    }
  } catch (err) {
    log(`[ARR Notifier] Non-fatal error communicating with ${target.label}: ${err.message || err}`);
  }

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables
  };
};

